type Review struct {
	Text   string
	Rating int
}

func GroupReviews(reviews []Review) map[int][]string {
	out := make(map[int][]string, 5)
	for _, r := range reviews {
		out[r.Rating] = append(out[r.Rating], r.Text)
	}
	return out
}

type Sale struct {
	Good string
	City string
}

func GroupBy[T any, K comparable, V any](items []T, key func(T) K, val func(T) V) map[K][]V {
	out := make(map[K][]V)
	for _, it := range items {
		k := key(it)
		out[k] = append(out[k], val(it))
	}
	return out
}

func GroupSales(sales []Sale) map[string][]string {
	return GroupBy(sales,
		func(s Sale) string { return s.City },
		func(s Sale) string { return s.Good })
}
```
Output: `map[1:[Bad Disliked] 3:[Meh] 4:[Good] 5:[Great As described]]`, `map[Kazan:[Item2] Moscow:[Item1 Item3]]`.

Complexity: O(n) time, O(n) memory. Order *within* each group follows the input order; the order of keys when ranging is random.

